package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.core.*;import net.minecraft.nbt.*;import net.minecraft.server.level.*;import net.minecraft.world.*;import net.minecraft.world.entity.*;import net.minecraft.world.item.*;import net.minecraft.world.level.*;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.*;import net.minecraft.world.phys.*;import java.util.*;
/** One controller per complete installation; no ticking or networked entity per model part. */
public final class DefenseBlockEntity extends BlockEntity implements PatriotLauncher{
 public UUID id=UUID.randomUUID(),owner;public String ownerName="",status="SERVICE";public int phase,selected;public boolean enabled,automatic;public UUID target,selectedLauncher;public final NonNullList<ItemStack>ammo=NonNullList.withSize(4,ItemStack.EMPTY);public ListTag contacts=new ListTag(),launchers=new ListTag();public UUID radarId;public String radarState="NO_RADAR";public long scanned,nextShot;private long sessionUntil,lastAction=-20,start;private float from=1,to=1;private boolean paused,removing;private int pending=-1;private UUID pendingTarget,pendingActor,pendingRadar;private boolean pendingAuto;private final float[]coverFrom=new float[4],coverTo=new float[4];private final long[]coverStart=new long[4],closeAt=new long[4];private int revision,seenRevision=-1,roundRobin;private long clearanceAt=Long.MIN_VALUE;private String clearanceCached="";
 public DefenseBlockEntity(BlockPos p,BlockState s){super(AddonBlockEntities.DEFENSE.get(),p,s);}public int kind(){return((DefenseBlock)getBlockState().getBlock()).kind;}public DefenseGeometry geometry(){return DefenseGeometry.MODELS[kind()];}public Direction facing(){return getBlockState().getValue(DefenseBlock.FACING);}
 public void restoreTag(CompoundTag n){loadWithComponents(n,level.registryAccess());}public CompoundTag stateTag(){return saveWithoutMetadata(level.registryAccess());}
 public UUID defenseId(){return id;}public UUID defenseOwner(){return owner;}public String defenseOwnerName(){return ownerName;}public ServerLevel defenseLevel(){return(ServerLevel)level;}public Vec3 defensePosition(){return Vec3.atCenterOf(worldPosition);}public boolean active(){return kind()==1&&phase==2&&enabled&&!removing;}
 public float pose(float partial){if(level==null||paused)return from;double duration=Math.max(1,Math.abs(to-from)*(kind()==0?80:60));double progress=Math.max(0,Math.min(1,(level.getGameTime()-start+partial)/duration));return(float)(from+(to-from)*progress);}public float cover(int i,float partial){if(level==null)return coverFrom[i];double t=Math.max(0,Math.min(1,(level.getGameTime()-coverStart[i]+partial)/16d));return(float)(coverFrom[i]+(coverTo[i]-coverFrom[i])*t);}public float[]covers(float partial){float[]v=new float[4];for(int i=0;i<4;i++)v[i]=cover(i,partial);return v;}
 public boolean canOperate(ServerPlayer p){if(level!=p.level()||!p.isAlive()||p.isSpectator()||InjuryServer.cannotOperate(p)||!DefenseData.allowed(defenseLevel(),owner,ownerName,p)||!level.mayInteract(p,worldPosition))return false;var panel=geometry().worldBox(worldPosition,facing(),geometry().panel).inflate(.35);if(panel.distanceToSqr(p.getEyePosition())>25)return false;var end=panel.getCenter();var ray=level.clip(new ClipContext(p.getEyePosition(),end,ClipContext.Block.OUTLINE,ClipContext.Fluid.NONE,p));return ray.getType()==HitResult.Type.MISS||level.getBlockState(ray.getBlockPos()).getBlock()instanceof DefenseBlock&&DefenseBlock.root(ray.getBlockPos(),level.getBlockState(ray.getBlockPos())).equals(worldPosition);}
 public boolean hostile(Entity e){return Mpl01Entity.airDrone(e)&&Adv01Targets.relation(defenseLevel(),owner,ownerName,e)==Adv01Targets.HOSTILE&&e.position().distanceToSqr(defensePosition())<=Math.pow(kind()==1?DefenseConfig.RANGE.get():Mpl01Config.RANGE.get(),2);}
 public void status(String code){if(!status.equals(code)){status=code;changed();}}public void changed(){setChanged();if(level!=null)level.sendBlockUpdated(worldPosition,getBlockState(),getBlockState(),3);}
 private void setCover(int slot,float value){coverFrom[slot]=cover(slot,0);coverTo[slot]=value;coverStart[slot]=level.getGameTime();changed();}
 public String clearance(){var box=geometry().worldBox(worldPosition,facing(),geometry().bounds);for(var p:BlockPos.betweenClosed(BlockPos.containing(box.minX,box.minY,box.minZ),BlockPos.containing(box.maxX-.00001,box.maxY-.00001,box.maxZ-.00001))){if(!level.hasChunkAt(p))return "UNLOADED";var s=level.getBlockState(p);if(!s.isAir()&&!(s.getBlock()instanceof DefenseBlock b&&b.kind==kind()&&DefenseBlock.root(p,s).equals(worldPosition)))return "BLOCKED";}return "";}
 public void deploy(){if(pending>=0||Arrays.stream(new double[]{cover(0,0),cover(1,0),cover(2,0),cover(3,0)}).anyMatch(v->v>.001)){status("COVER_OPEN");return;}String why=clearance();if(!why.isEmpty()){status(why);return;}from=pose(0);to=phase==2||phase==1?1:0;phase=to==0?1:3;start=level.getGameTime();paused=false;status=phase==1?"DEPLOYING":"RETRACTING";if(kind()==1){contacts=new ListTag();revision++;}level.playSound(null,worldPosition,net.minecraft.sounds.SoundEvents.IRON_DOOR_OPEN,net.minecraft.sounds.SoundSource.BLOCKS,.7f,.7f);changed();}
 private boolean load(ServerPlayer p,boolean unload){if(phase==1||phase==3||pending>=0||level.getGameTime()<nextShot)return false;if(unload){var s=ammo.get(selected);if(s.isEmpty())return false;var copy=s.copy();if(!p.getInventory().add(copy)){status("INVENTORY_FULL");return false;}ammo.set(selected,ItemStack.EMPTY);}else{if(!ammo.get(selected).isEmpty())return false;boolean found=false;for(int i=0;i<p.getInventory().getContainerSize();i++){var s=p.getInventory().getItem(i);if(s.is(AddonItems.PM01.get())){ammo.set(selected,s.split(1));found=true;break;}}if(!found){status("NO_AMMO");return false;}}p.getInventory().setChanged();status=phase==2?"READY":"SERVICE";changed();return true;}
 private boolean readySpace(){long now=level.getGameTime();if(clearanceAt!=now){clearanceCached=clearance();clearanceAt=now;}return clearanceCached.isEmpty();}
 public boolean defenseAvailable(){return kind()==0&&phase==2&&pending<0&&level.getGameTime()>=nextShot&&ammo.stream().anyMatch(s->s.is(AddonItems.PM01.get()))&&readySpace();}
 private String fireCheck(int slot,Entity goal){if(phase!=2)return "NOT_READY";if(level.getGameTime()<nextShot)return "COOLDOWN";if(slot<0||slot>=4||!ammo.get(slot).is(AddonItems.PM01.get()))return "EMPTY";if(!hostile(goal))return "NO_TARGET";if(Pm01Entity.active(defenseLevel())>=Mpl01Config.MAX_MISSILES.get())return "MISSILE_LIMIT";String why=clearance();if(!why.isEmpty())return why;var exit=geometry().exit(worldPosition,facing(),slot,0);var direction=geometry().launchDirection(worldPosition,facing(),slot,0);for(double x:new double[]{-.36,0,.36}){var offset=new Vec3(x,0,0);var ray=DefenseBlock.clipOutside(this,exit.add(offset).add(direction.scale(.12)),exit.add(offset).add(direction.scale(6.4)));if(ray.getType()!=HitResult.Type.MISS)return "BLOCKED";}if(!Hgd01Lasers.loaded(defenseLevel(),exit,exit.add(direction.scale(6.4))))return "UNLOADED";return "";}
 public boolean request(ServerPlayer actor,UUID goal,UUID radar,boolean auto){if(kind()!=0||pending>=0)return false;if(radar==null){if(actor==null||!canOperate(actor))return false;}else if(!DefenseData.get(defenseLevel()).radarAllows(defenseLevel(),radar,id,actor,auto))return false;int slot=selected;if(!ammo.get(slot).is(AddonItems.PM01.get())){slot=-1;for(int i=0;i<4;i++)if(ammo.get(i).is(AddonItems.PM01.get())){slot=i;break;}}var targetEntity=goal==null?null:defenseLevel().getEntity(goal);String why=fireCheck(slot,targetEntity);if(!why.isEmpty()){status(why);return false;}selected=slot;target=goal;pending=slot;pendingTarget=goal;pendingActor=actor==null?null:actor.getUUID();pendingRadar=radar;pendingAuto=auto;DefenseData.get(defenseLevel()).reserve(id,goal,level.getGameTime());setCover(slot,1);status("OPENING_COVER");return true;}
 public boolean defenseRequest(ServerPlayer actor,UUID goal,UUID radar){return request(actor,goal,radar,actor==null);}
 private void pending(){if(pending<0)return;int slot=pending;var actor=pendingActor==null?null:defenseLevel().getServer().getPlayerList().getPlayer(pendingActor);boolean allowed=pendingRadar==null?actor!=null&&canOperate(actor):DefenseData.get(defenseLevel()).radarAllows(defenseLevel(),pendingRadar,id,actor,pendingAuto);var goal=pendingTarget==null?null:defenseLevel().getEntity(pendingTarget);String why=allowed?fireCheck(slot,goal):"DENIED";if(!why.isEmpty()){pending=-1;DefenseData.get(defenseLevel()).release(id);setCover(slot,0);status(why);return;}if(cover(slot,0)<.999)return;
  var exit=geometry().exit(worldPosition,facing(),slot,0);var direction=geometry().launchDirection(worldPosition,facing(),slot,0);var payload=ammo.get(slot);ammo.set(slot,ItemStack.EMPTY);var missile=PatriotShots.spawn(this,actor,goal,exit.subtract(direction.scale(2.675)),direction);if(missile==null){ammo.set(slot,payload);status("REFUSED");}else{nextShot=level.getGameTime()+Mpl01Config.RELOAD.get();level.playSound(null,exit.x,exit.y,exit.z,com.atsuishio.superbwarfare.init.ModSounds.JAVELIN_FIRE_3P.get(),net.minecraft.sounds.SoundSource.HOSTILE,1,1);status="FIRED";}pending=-1;closeAt[slot]=level.getGameTime()+8;DefenseData.get(defenseLevel()).release(id);changed();}
 private void scan(){double range=kind()==1?DefenseConfig.RANGE.get():Mpl01Config.RANGE.get();var found=defenseLevel().getEntities((Entity)null,new AABB(defensePosition(),defensePosition()).inflate(range),this::hostile);found.sort(Comparator.comparingDouble(e->e.position().distanceToSqr(defensePosition())));var list=new ListTag();for(var e:found){var n=new CompoundTag();n.putUUID("UUID",e.getUUID());n.putInt("Id",e.getId());n.putString("Name",e.getName().getString());n.putDouble("Distance",e.position().distanceTo(defensePosition()));n.putDouble("Height",e.getY()-worldPosition.getY());list.add(n);if(list.size()>=DefenseConfig.CONTACTS.get())break;}contacts=list;scanned=level.getGameTime();revision++;if(target!=null&&!hostile(defenseLevel().getEntity(target)))target=null;changed();}
 private void updateLinks(){var data=DefenseData.get(defenseLevel());var own=data.site(id);if(own==null)return;if(kind()==0){radarId=own.radar;var radar=data.radar(defenseLevel(),radarId);radarState=radarId==null?"NO_RADAR":radar==null?"UNLOADED":radar.active()?"READY":"OFF";if(radar!=null&&radar.active()&&seenRevision!=radar.revision){contacts=radar.contacts.copy();for(var contact:contacts){var n=(CompoundTag)contact;var target=defenseLevel().getEntity(n.getUUID("UUID"));if(target!=null){n.putDouble("Distance",target.position().distanceTo(defensePosition()));n.putDouble("Height",target.getY()-worldPosition.getY());}}scanned=radar.scanned;seenRevision=radar.revision;changed();}else if(radarId!=null&&(radar==null||!radar.active())&&!contacts.isEmpty()&&sessionUntil<level.getGameTime()){contacts=new ListTag();changed();}return;}var list=new ListTag();for(var linked:List.copyOf(own.links)){var s=data.site(linked);if(s==null||s.removed){own.links.remove(linked);data.setDirty();continue;}var launcher=data.launcher(defenseLevel(),linked);var n=new CompoundTag();n.putUUID("UUID",linked);n.putString("Name",s.kind==4?"NDC-01":s.kind==3?"ADC-01":s.kind==2?"MPL-01":"PL-01");n.putString("Status",launcher==null?"UNLOADED":launcher.defenseAvailable()?"READY":"NOT_READY");n.putDouble("Distance",launcher==null?Vec3.atCenterOf(s.root).distanceTo(defensePosition()):launcher.defensePosition().distanceTo(defensePosition()));list.add(n);}launchers=list;changed();}
 private void automatic(){if(!active()||!automatic||contacts.isEmpty()||level.getGameTime()-scanned>DefenseConfig.SCAN.get()*3L)return;var data=DefenseData.get(defenseLevel());var own=data.site(id);if(own==null||own.links.isEmpty())return;var ids=List.copyOf(own.links);for(var v:contacts){var contact=(CompoundTag)v;UUID goal=contact.getUUID("UUID");if(data.assigned(defenseLevel(),goal)||!hostile(defenseLevel().getEntity(goal)))continue;for(int i=0;i<ids.size();i++){var linked=ids.get(Math.floorMod(roundRobin+i,ids.size()));var launcher=data.launcher(defenseLevel(),linked);if(launcher!=null&&launcher.defenseAvailable()&&launcher.defenseRequest(null,goal,id)){roundRobin=(roundRobin+i+1)%ids.size();return;}}}}
 public void control(ServerPlayer p,int action,int slot,UUID value){if(!canOperate(p)||action<0||action>13)return;sessionUntil=level.getGameTime()+120;if(kind()==0&&pending>=0&&(action==2||action==5||action==13)){status("OPENING_COVER");return;}if(action==0||action==9){if(kind()==0&&(radarId==null||!radarState.equals("READY"))&&level.getGameTime()-scanned>=DefenseConfig.SCAN.get())scan();return;}if(level.getGameTime()-lastAction<3)return;lastAction=level.getGameTime();if(action==1)deploy();else if(action==2&&kind()==0&&slot>=0&&slot<4){selected=slot;changed();}else if(action==3&&kind()==0)load(p,false);else if(action==4&&kind()==0)load(p,true);else if(action==5){boolean present=false;for(var v:contacts)if(((CompoundTag)v).getUUID("UUID").equals(value))present=true;if(present&&hostile(defenseLevel().getEntity(value))){target=value;changed();}else status("NO_TARGET");}else if(action==6&&kind()==0)request(p,target,null,false);else if(action==7&&kind()==1){enabled=!enabled;contacts=new ListTag();revision++;status=enabled?"ON":"OFF";changed();}else if(action==8&&kind()==1){automatic=!automatic;changed();}else if(action==10&&kind()==1){var own=DefenseData.get(defenseLevel()).site(id);if(own!=null&&own.links.contains(value)){selectedLauncher=value;changed();}}else if(action==11&&kind()==1&&selectedLauncher!=null){var launcher=DefenseData.get(defenseLevel()).launcher(defenseLevel(),selectedLauncher);if(launcher==null||target==null||!launcher.defenseRequest(p,target,id))status("REFUSED");}else if(action==12&&kind()==1&&selectedLauncher!=null){var data=DefenseData.get(defenseLevel());var own=data.site(id);if(own!=null&&own.links.contains(selectedLauncher))data.unlink(selectedLauncher);selectedLauncher=null;updateLinks();}else if(action==13&&kind()==0){for(int i=1;i<=4;i++){int candidate=(selected+i)%4;if(!ammo.get(candidate).isEmpty()){selected=candidate;changed();break;}}}}
 public static void tick(Level l,BlockPos p,BlockState s,DefenseBlockEntity b){if(l.isClientSide||b.removing)return;long now=l.getGameTime();if(b.phase==1||b.phase==3){String why=b.clearance();boolean blocked=!why.isEmpty()||l.getEntities((Entity)null,b.geometry().worldBox(p,b.facing(),b.geometry().bounds),e->e instanceof net.minecraft.world.entity.LivingEntity&&!e.isSpectator()).stream().anyMatch(e->e.getBoundingBox().minY>p.getY()+2.6);if(blocked&&!b.paused){b.from=b.pose(0);b.paused=true;b.status("BLOCKED");b.changed();}else if(!blocked&&b.paused){b.paused=false;b.start=now;b.changed();}if(!b.paused&&Math.abs(b.pose(0)-b.to)<.0001){b.from=b.to;b.phase=b.to==0?2:0;b.status=b.phase==2?"READY":"SERVICE";b.changed();}}
  if(b.kind()==0){b.pending();for(int i=0;i<4;i++)if(b.closeAt[i]>0&&now>=b.closeAt[i]){b.closeAt[i]=0;b.setCover(i,0);}}
  if(Math.floorMod(now+p.asLong(),DefenseConfig.SCAN.get())==0){b.updateLinks();if(b.active())b.scan();else if(b.kind()==0&&(b.radarId==null||!b.radarState.equals("READY"))&&b.sessionUntil>=now)b.scan();}
  if(b.active()&&b.automatic&&Math.floorMod(now+p.asLong(),DefenseConfig.AUTO_INTERVAL.get())==0)b.automatic();
 }
 public boolean remove(ServerPlayer p,boolean pack){if(removing||p!=null&&(!canOperate(p)||phase!=0||pose(0)<.999||pending>=0))return false;if(p!=null){for(var c:geometry().cells){var at=geometry().cell(worldPosition,facing(),c);if(!level.hasChunkAt(at)||!level.mayInteract(p,at))return false;var event=new net.neoforged.neoforge.event.level.BlockEvent.BreakEvent(level,at,level.getBlockState(at),p);if(net.neoforged.neoforge.common.NeoForge.EVENT_BUS.post(event).isCanceled())return false;}}removing=true;if(pack&&p!=null&&!p.isCreative()){var stack=new ItemStack(kind()==0?AddonItems.PL01.get():AddonItems.DR01.get());var tag=DefenseItem.data(stack);tag.put("Installation",saveWithoutMetadata(level.registryAccess()));DefenseItem.data(stack,tag);net.neoforged.neoforge.items.ItemHandlerHelper.giveItemToPlayer(p,stack);}else if(!pack)for(var stack:ammo)if(!stack.isEmpty())net.minecraft.world.Containers.dropItemStack(level,worldPosition.getX()+.5,worldPosition.getY()+1,worldPosition.getZ()+.5,stack);DefenseData.get(defenseLevel()).remove(defenseLevel(),id);return true;}
 @Override public void onLoad(){super.onLoad();if(level instanceof ServerLevel l){start=l.getGameTime();pending=-1;for(int i=0;i<4;i++){coverTo[i]=0;coverStart[i]=l.getGameTime();}l.getServer().tell(new net.minecraft.server.TickTask(l.getServer().getTickCount()+1,()->{if(!isRemoved()){DefenseData.get(l).register(new DefenseData.Site(id,kind(),worldPosition,facing(),owner,ownerName));updateLinks();changed();}}));}}
 @Override protected void saveAdditional(CompoundTag n,net.minecraft.core.HolderLookup.Provider registry){super.saveAdditional(n,registry);n.putUUID("Id",id);if(owner!=null)n.putUUID("Owner",owner);n.putString("OwnerName",ownerName);n.putInt("Phase",phase);n.putFloat("Pose",pose(0));n.putBoolean("Paused",paused);n.putFloat("To",to);n.putBoolean("Enabled",enabled);n.putBoolean("Automatic",automatic);n.putInt("Selected",selected);n.putLong("NextShot",nextShot);n.putInt("Cooldown",(int)Math.max(0,nextShot-level.getGameTime()));net.minecraft.world.ContainerHelper.saveAllItems(n,ammo,registry);if(target!=null)n.putUUID("Target",target);if(selectedLauncher!=null)n.putUUID("SelectedLauncher",selectedLauncher);n.putString("Status",status);n.put("Contacts",contacts);n.put("Launchers",launchers);n.putLong("Scanned",scanned);if(radarId!=null)n.putUUID("Radar",radarId);n.putString("RadarState",radarState);for(int i=0;i<4;i++){n.putFloat("Cover"+i,cover(i,0));n.putFloat("CoverTo"+i,coverTo[i]);}}
 @Override protected void loadAdditional(CompoundTag n,net.minecraft.core.HolderLookup.Provider registry){super.loadAdditional(n,registry);if(n.hasUUID("Id"))id=n.getUUID("Id");owner=n.hasUUID("Owner")?n.getUUID("Owner"):null;ownerName=n.getString("OwnerName");phase=Math.max(0,Math.min(3,n.getInt("Phase")));from=n.contains("Pose")?n.getFloat("Pose"):1;to=n.contains("To")?n.getFloat("To"):from;paused=n.getBoolean("Paused");start=level==null?0:level.getGameTime();enabled=n.getBoolean("Enabled");automatic=n.getBoolean("Automatic");selected=Math.max(0,Math.min(3,n.getInt("Selected")));nextShot=n.contains("NextShot")?n.getLong("NextShot"):(level==null?0:level.getGameTime())+Math.max(0,Math.min(1200,n.getInt("Cooldown")));for(int i=0;i<4;i++)ammo.set(i,ItemStack.EMPTY);net.minecraft.world.ContainerHelper.loadAllItems(n,ammo,registry);target=n.hasUUID("Target")?n.getUUID("Target"):null;selectedLauncher=n.hasUUID("SelectedLauncher")?n.getUUID("SelectedLauncher"):null;status=n.contains("Status")?n.getString("Status"):"SERVICE";contacts=n.getList("Contacts",10);launchers=n.getList("Launchers",10);scanned=n.getLong("Scanned");radarId=n.hasUUID("Radar")?n.getUUID("Radar"):null;radarState=n.getString("RadarState");for(int i=0;i<4;i++){coverFrom[i]=n.getFloat("Cover"+i);coverTo[i]=n.getFloat("CoverTo"+i);coverStart[i]=start;}}
 @Override public CompoundTag getUpdateTag(net.minecraft.core.HolderLookup.Provider registry){return saveWithoutMetadata(level.registryAccess());}@Override public net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket getUpdatePacket(){return net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket.create(this);}public AABB getRenderBoundingBox(){return geometry().worldBox(worldPosition,facing(),geometry().bounds).inflate(.15);}
}
